{"op":"add","path":"/root","value":"page"}
{"op":"add","path":"/elements/page","value":{"type":"Stack","props":{"direction":"vertical","gap":"xl"},"children":["header","invoices"]}}
{"op":"add","path":"/elements/header","value":{"type":"ResultHeader","props":{"eyebrow":"Invoice extraction","title":"Your invoice, read back","subtitle":"What we found on the document, ready to file."},"children":[]}}
{"op":"add","path":"/elements/invoices","value":{"type":"Stack","props":{"direction":"vertical","gap":"xl"},"repeat":{"statePath":"/result","key":"invoice_id"},"children":["invoice-section","invoice-separator"]}}
{"op":"add","path":"/elements/invoice-section","value":{"type":"Section","props":{"title":{"$item":"vendor"}},"children":["invoice-date","money-band","record-split","raw-text"]}}
{"op":"add","path":"/elements/invoice-date","value":{"type":"DateText","props":{"value":{"$item":"issue_date"},"style":"long","tone":"accent"},"children":[]}}
{"op":"add","path":"/elements/money-band","value":{"type":"Grid","props":{"columns":3,"gap":"md"},"children":["fact-total","fact-net","fact-vat","vat-rates"]}}
{"op":"add","path":"/elements/fact-total","value":{"type":"Fact","props":{"label":"Total paid","value":{"$item":"amount_incl_tax"},"detail":"incl. tax"},"children":[]}}
{"op":"add","path":"/elements/fact-net","value":{"type":"Fact","props":{"label":"Net","value":{"$item":"amount_excl_tax"},"detail":"before tax"},"children":[]}}
{"op":"add","path":"/elements/fact-vat","value":{"type":"Fact","props":{"label":"VAT","value":{"$item":"vat_amount"}},"children":[]}}
{"op":"add","path":"/elements/vat-rates","value":{"type":"MthdsResult","props":{"path":"vat_rates"},"children":[]}}
{"op":"add","path":"/elements/record-split","value":{"type":"Split","props":{"ratio":"2:1","gap":"xl"},"children":["record-column","parties-rail"]}}
{"op":"add","path":"/elements/record-column","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["record-heading","record-description","category-line"]}}
{"op":"add","path":"/elements/record-heading","value":{"type":"Heading","props":{"text":"What was bought","level":"h3"},"children":[]}}
{"op":"add","path":"/elements/record-description","value":{"type":"Text","props":{"text":{"$item":"description"},"variant":"body"},"children":[]}}
{"op":"add","path":"/elements/category-line","value":{"type":"Stack","props":{"direction":"horizontal","gap":"sm","align":"center"},"children":["category-badge","category-explanation"]}}
{"op":"add","path":"/elements/category-badge","value":{"type":"Badge","props":{"text":{"$item":"category/category"},"variant":"secondary"},"children":[]}}
{"op":"add","path":"/elements/category-explanation","value":{"type":"Text","props":{"text":{"$item":"category/explanation"},"variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/parties-rail","value":{"type":"Stack","props":{"direction":"vertical","gap":"none"},"children":["detail-invoice-number","detail-order-id","detail-time","detail-vendor-address","detail-siret","detail-vat-number","detail-company","detail-company-address"]}}
{"op":"add","path":"/elements/detail-invoice-number","value":{"type":"Detail","props":{"label":"Invoice no.","value":{"$item":"invoice_number"}},"children":[]}}
{"op":"add","path":"/elements/detail-order-id","value":{"type":"Detail","props":{"label":"Order ID","value":{"$item":"invoice_id"}},"children":[]}}
{"op":"add","path":"/elements/detail-time","value":{"type":"Detail","props":{"label":"Time","value":{"$item":"time"}},"children":[]}}
{"op":"add","path":"/elements/detail-vendor-address","value":{"type":"Detail","props":{"label":"Vendor address","value":{"$item":"vendor_address"}},"children":[]}}
{"op":"add","path":"/elements/detail-siret","value":{"type":"Detail","props":{"label":"SIRET","value":{"$item":"vendor_siret"}},"children":[]}}
{"op":"add","path":"/elements/detail-vat-number","value":{"type":"Detail","props":{"label":"VAT number","value":{"$item":"vendor_vat_number"}},"children":[]}}
{"op":"add","path":"/elements/detail-company","value":{"type":"Detail","props":{"label":"Billed to","value":{"$item":"company_name"}},"children":[]}}
{"op":"add","path":"/elements/detail-company-address","value":{"type":"Detail","props":{"label":"Billing address","value":{"$item":"company_address"}},"children":[]}}
{"op":"add","path":"/elements/raw-text","value":{"type":"Collapsible","props":{"title":"Show the original text","defaultOpen":false},"children":["raw-text-body"]}}
{"op":"add","path":"/elements/raw-text-body","value":{"type":"MthdsResult","props":{"path":"text","hideLabel":true},"children":[]}}
{"op":"add","path":"/elements/invoice-separator","value":{"type":"Separator","props":{"orientation":"horizontal"},"children":[]}}
